<script setup lang="ts">
import { computed, ref } from 'vue';
const emit = defineEmits<{ save: [payload: { name: string; graph: Record<string, unknown>; imageNodeIds: string[]; audioNodeIds: string[] }] }>();
const open = ref(false); const step = ref(1); const name = ref('H3 workflow'); const json = ref(''); const imageIds = ref(''); const audioIds = ref(''); const error = ref('');
const graph = computed(() => { try { const value = JSON.parse(json.value); return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null; } catch { return null; } });
const boundary = computed(() => { if (!graph.value) return null; const entries = Object.entries(graph.value); const classes = (name: string) => entries.filter(([, node]) => (node as any)?.class_type === name).map(([id]) => id); const h3 = classes('MiniMaxH3ReferenceToVideo'); const noise = classes('RandomNoise'); const save = classes('SaveVideo'); const images = classes('LoadImage'); const audios = classes('LoadAudio'); const imageBindings = imageIds.value.split(',').map((v) => v.trim()).filter(Boolean); const audioBindings = audioIds.value.split(',').map((v) => v.trim()).filter(Boolean); const bindingsValid = imageBindings.every((id) => images.includes(id)) && audioBindings.every((id) => audios.includes(id)); return { h3, noise, save, images, audios, valid: h3.length === 1 && noise.length === 1 && save.length === 1 && bindingsValid }; });
function importFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { json.value = String(reader.result ?? ''); step.value = 2; error.value = ''; }; reader.readAsText(file); }
function next() { error.value = ''; if (step.value === 1 && !graph.value) { error.value = 'Загрузите API-format JSON workflow'; return; } if (step.value === 2 && (!imageIds.value.trim() || !boundary.value?.valid)) { error.value = 'Нужны image bindings и уникальные H3, RandomNoise и SaveVideo узлы'; return; } step.value = Math.min(4, step.value + 1); }
function save() { if (!graph.value || !boundary.value?.valid) { error.value = 'Boundary не прошёл проверку'; return; } emit('save', { name: name.value.trim() || 'H3 workflow', graph: graph.value, imageNodeIds: imageIds.value.split(',').map((v) => v.trim()).filter(Boolean), audioNodeIds: audioIds.value.split(',').map((v) => v.trim()).filter(Boolean) }); step.value = 4; }
</script>
<template><section class="workflow-wizard"><button type="button" class="uk-button uk-button-default" @click="open = !open">{{ open ? 'Свернуть мастер' : 'Импортировать workflow H3' }}</button><div v-if="open" class="wizard-panel"><div class="wizard-steps"><span v-for="n in 4" :key="n" :class="{active: step >= n}">{{ n }}</span></div><h3>Настройка H3 workflow</h3><label>Название профиля<input v-model="name" class="uk-input"></label><label v-if="step === 1">API-format JSON<input type="file" accept="application/json,.json" class="uk-input" @change="importFile"><textarea v-model="json" class="uk-textarea" rows="4" placeholder="Или вставьте JSON графа"></textarea></label><div v-else-if="step === 2"><label>Image node IDs<input v-model="imageIds" class="uk-input" placeholder="7,8,9"></label><label>Audio node IDs<input v-model="audioIds" class="uk-input" placeholder="10,11"></label><p class="uk-text-small">Boundary: H3 {{ boundary?.h3.join(', ') || '—' }} · Noise {{ boundary?.noise.join(', ') || '—' }} · Save {{ boundary?.save.join(', ') || '—' }}</p></div><p v-else-if="step === 3" class="uk-text-small">Boundary {{ boundary?.valid ? 'подтверждён' : 'не прошёл проверку' }}. Нажмите «Проверить и активировать», чтобы создать immutable revision.</p><p v-else class="uk-text-success">Профиль сохранён и готов к выбору в shot editor.</p><p v-if="error" class="uk-text-danger">{{ error }}</p><div class="wizard-actions"><button v-if="step < 3" type="button" class="uk-button uk-button-default" @click="next">Далее</button><button v-if="step === 2" type="button" class="uk-button uk-button-default" @click="next">Проверить</button><button v-if="step === 3" type="button" class="uk-button uk-button-primary" @click="save">Проверить и активировать</button></div></div></section></template>
<style scoped>
.workflow-wizard{margin:0 0 14px}.wizard-panel{margin-top:10px;padding:14px;border:1px solid var(--line,#303742);border-radius:10px;background:var(--surface-raised,#20252d)}.wizard-panel label{display:block;margin:8px 0}.wizard-panel textarea{margin-top:6px}.wizard-steps{display:flex;gap:8px;margin-bottom:10px}.wizard-steps span{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;background:#303742;color:#97a1af;font-size:12px}.wizard-steps span.active{background:#367ed7;color:#fff}.wizard-actions{display:flex;gap:8px;margin-top:12px}
</style>
